const input = require('fs').readFileSync('/dev/stdin', 'utf8').split(/\s+/).filter(Boolean);
const n = +input[0];
const last = new Int32Array(100001).fill(-1);
let start = 0, best = 0;
for (let i = 0; i < n; i++) {
